def _parse_float(text):
    # A finite decimal token may still overflow a double; that is a plain
    # (non-integer) number and is rejected later by the schema checks.
    return float(text)


def parse_json(text):
    return json.loads(
        text,
        object_pairs_hook=_object_pairs,
        parse_constant=_parse_constant,
        parse_float=_parse_float,
    )


